// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"ESS combines science and society. It starts with how people see the environment and how systems work.","blocks":[{"t":"key","text":"Environmental value systems (EVS) range from ecocentric (nature-centered, emphasizing limits and ethics) to technocentric (technology and human ingenuity solve problems), with anthropocentric (human-centered management) in between. Your perspective affects how you judge environmental issues."},{"t":"p","text":"Systems thinking: a system has inputs, outputs, storages and flows (transfers and transformations). Open systems exchange matter and energy; closed systems exchange only energy; isolated systems exchange neither."},{"t":"p","text":"Feedback: negative feedback stabilizes a system; positive feedback amplifies change and can push a system past a tipping point."},{"t":"lab","kind":"lab","title":"Lake storage and flows","aim":"A lake receives a steady inflow, and its outflow increases with how much water it stores. Watch the storage over time.","sets":[{"name":"t","start":5,"label":"Time (years)","min":0,"max":30,"step":1},{"name":"In","start":20,"label":"Inflow (million m³/year)","min":5,"max":50,"step":1}],"outs":[{"name":"Seq","expr":"In/0.2","label":"Equilibrium storage (million m³)"},{"name":"S","expr":"Seq + (50 - Seq)*exp(-0.2*t)","label":"Storage (million m³)"},{"name":"Out","expr":"0.2*S","label":"Outflow (million m³/year)"}],"steps":["Record the storage every 5 years.","Raise the inflow, as in a wet decade, and see where it settles."],"noise":2,"result":"When outflow rises with storage, the system has negative feedback and settles at a steady-state equilibrium where inputs equal outputs. Change the input and it moves to a new equilibrium.","plot":{"x":"t","y":"S"}}]},{"say":"Sustainability means meeting our needs without compromising future generations. ESS gives tools to measure it.","blocks":[{"t":"key","text":"Sustainability has environmental, social and economic dimensions. Natural capital (resources and ecosystem services) generates natural income; living sustainably means using only the income, not depleting the capital."},{"t":"p","text":"Ecological footprint measures the area needed to support a population's consumption; carbon and water footprints measure specific impacts. Planetary boundaries define safe operating limits for Earth systems (such as climate, biodiversity loss and nitrogen cycles)."},{"t":"p","text":"Environmental impact assessments (EIAs) evaluate projects before they're built. The UN Sustainable Development Goals set global targets."}]}],[{"say":"Ecology studies how organisms interact with each other and their environment.","blocks":[{"t":"key","text":"A species' niche includes its habitat and role. Populations are limited by biotic and abiotic factors; carrying capacity is the maximum sustainable population. Population growth follows J-curves (exponential) or S-curves (logistic)."},{"t":"p","text":"Energy flows through food chains and webs; only about 10% passes to the next trophic level. Pyramids of numbers, biomass and productivity show this. Gross primary productivity (GPP) minus respiration equals net primary productivity (NPP)."},{"t":"p","text":"Biogeochemical cycles (carbon, nitrogen) move matter through ecosystems; human activities disrupt them."}]},{"say":"Biodiversity is under threat. Conservation science aims to protect it.","blocks":[{"t":"key","text":"Biodiversity includes genetic, species and habitat diversity. Biodiversity hotspots have high endemism and high threat. The Simpson's diversity index measures diversity using richness and evenness."},{"t":"p","text":"Threats: habitat loss and fragmentation, invasive species, pollution, overexploitation and climate change. The IUCN Red List categorizes extinction risk."},{"t":"p","text":"Conservation approaches: species-based (captive breeding, CITES) and habitat-based (protected areas, wildlife corridors). Reserve design considers size, shape, edge effects and connectivity."},{"t":"tip","text":"When evaluating a conservation strategy, weigh both sides: protecting habitat saves many species at once, while species-based methods can rescue critically endangered animals quickly."},{"t":"lab","kind":"lab","title":"Simpson's diversity in quadrats","aim":"Count three plant species in quadrats and calculate Simpson's diversity index.","sets":[{"name":"a","start":25,"label":"Species A count","min":1,"max":100,"step":1},{"name":"b","start":25,"label":"Species B count","min":1,"max":100,"step":1},{"name":"c","start":25,"label":"Species C count","min":1,"max":100,"step":1}],"outs":[{"name":"N","expr":"a + b + c","label":"Total plants"},{"name":"D","expr":"1 - ((a/N)^2 + (b/N)^2 + (c/N)^2)","label":"Simpson's index (1 − D)"}],"steps":["Record the index when all species are equal, then make species A dominant."],"noise":0,"result":"Diversity depends on both richness and evenness. The index is highest when species are equally common and falls as one species dominates, even though the number of species stays the same.","plot":{"x":"a","y":"D"}}]}],[{"say":"Water is essential and unevenly distributed. Managing it sustainably is a global challenge.","blocks":[{"t":"key","text":"The hydrological cycle moves water through evaporation, transpiration, condensation, precipitation, infiltration and runoff. Only about 2.5% of Earth's water is fresh, and most is locked in ice."},{"t":"p","text":"Water scarcity can be physical (not enough water) or economic (lack of infrastructure). Solutions include conservation, desalination, rainwater harvesting and better irrigation."},{"t":"p","text":"Water pollution: eutrophication from nitrates and phosphates causes algal blooms and hypoxia. Indicator species and biochemical oxygen demand (BOD) measure water quality."},{"t":"p","text":"Aquatic food production: overfishing depletes stocks; maximum sustainable yield (MSY), quotas, marine protected areas and sustainable aquaculture help."},{"t":"lab","kind":"lab","title":"Fishing effort and sustainable yield","aim":"Add more fishing boats to a fishery and record the long-term sustainable catch.","sets":[{"name":"E","start":30,"label":"Fishing effort (boats)","min":0,"max":100,"step":1}],"outs":[{"name":"Y","expr":"0.01*E*1000*max(1 - 0.01*E, 0)","label":"Sustainable catch (tonnes/year)"},{"name":"stock","expr":"1000*max(1 - 0.01*E, 0)","label":"Fish stock (tonnes)"}],"steps":["Record the catch for at least 6 levels of effort.","Find the effort that gives maximum sustainable yield."],"noise":3,"result":"Catch rises with effort only up to a point (MSY at 50 boats here), then falls as the stock is overfished. Beyond MSY more boats catch fewer fish, which is why quotas and limits on effort matter.","plot":{"x":"E","y":"Y"}}]},{"say":"Soil feeds the world. How we farm determines whether soil stays healthy.","blocks":[{"t":"key","text":"Soil is a system of mineral particles, organic matter, water, air and organisms. Soil texture (sand, silt, clay) affects drainage and fertility; loam is ideal for farming."},{"t":"p","text":"Soil degradation: erosion (from overgrazing, deforestation and overcultivation), salinization (from irrigation), nutrient depletion and desertification. Conservation: terracing, contour plowing, cover crops, crop rotation and no-till farming."},{"t":"p","text":"Food systems: commercial vs. subsistence farming, intensive vs. extensive. Efficiency: eating lower on the food chain uses less land and energy. Food waste and unequal distribution affect food security."}]}],[{"say":"Human activity is changing the atmosphere, with global consequences.","blocks":[{"t":"key","text":"The atmosphere's greenhouse gases (CO₂, CH₄, N₂O, water vapor) trap infrared radiation. Enhanced greenhouse effect from burning fossil fuels and deforestation causes global warming."},{"t":"p","text":"Impacts: rising sea levels, extreme weather, glacier retreat, ocean acidification, species range shifts and threats to food and water security. Feedback loops (melting permafrost releasing methane, ice-albedo feedback) can accelerate change."},{"t":"p","text":"Responses: mitigation (reducing emissions, renewable energy, carbon capture, reforestation) and adaptation (flood defenses, drought-resistant crops). International agreements: the Kyoto Protocol and the Paris Agreement."},{"t":"p","text":"Stratospheric ozone depletion by CFCs was addressed by the Montreal Protocol, a successful example of global cooperation."}]},{"say":"Population growth and urbanization shape resource use and environmental impact.","blocks":[{"t":"key","text":"Human population growth is analyzed with birth and death rates, fertility rates and the demographic transition model. Age–sex pyramids show population structure. Doubling time ≈ 70 ÷ growth rate (%)."},{"t":"p","text":"Natural resources: renewable, replenishable and non-renewable. Energy choices balance cost, availability, reliability and environmental impact; a sustainable energy mix increases renewables."},{"t":"p","text":"Urban systems: cities concentrate people and consumption, creating heat islands, pollution and waste. Sustainable cities use public transport, green spaces, efficient buildings and circular economy approaches (reduce, reuse, recycle)."},{"t":"ex","problem":"A country's population grows at 2% per year. Estimate its doubling time.","steps":["70 ÷ 2"],"answer":"about 35 years"},{"t":"lab","kind":"lab","title":"How many Earths?","aim":"Change the average ecological footprint and population to see how many Earths' worth of biocapacity humanity needs.","sets":[{"name":"fp","start":2.6,"label":"Footprint per person (gha)","min":1,"max":10,"step":0.1},{"name":"P","start":8,"label":"Population (billions)","min":4,"max":11,"step":0.5}],"outs":[{"name":"need","expr":"fp*P","label":"Total footprint (billion gha)"},{"name":"earths","expr":"need/12.2","label":"Earths needed"}],"steps":["Record the Earths needed for the world average (2.6 gha) and a high-income country (about 7 gha).","Find the footprint per person that would fit within one Earth."],"noise":0,"result":"Earth has about 12.2 billion global hectares of biocapacity. At today's average footprint humanity uses about 1.7 Earths; if everyone lived like high-income countries we'd need over 4.","plot":{"x":"fp","y":"earths"}}]}]];
export default text;
